const (
	TokenMode_default = 0
)

func NewLexer(sc *service.Container) lexer.Lexer {
	modes := make([]*lexer.TokenMode, 1)
	modes[TokenMode_default] = lexer.NewTokenMode("default",
		lexer.UseTokenType(Keyword_module),
		lexer.UseTokenType(Keyword_Semicolon),
		lexer.UseTokenType(Keyword_import),
		lexer.UseTokenType(Keyword_export),
		lexer.UseTokenType(Keyword_game),
		lexer.UseTokenType(Keyword_from),
		lexer.UseTokenType(Keyword_story),
		lexer.UseTokenType(Keyword_LeftBrace),
		lexer.UseTokenType(Keyword_RightBrace),
		lexer.UseTokenType(Keyword_board),
		lexer.UseTokenType(Keyword_after),
		lexer.UseTokenType(Keyword_text),
		lexer.UseTokenType(Keyword_arrow),
		lexer.UseTokenType(Keyword_DashGreaterThan),
		lexer.UseTokenType(Keyword_prompt),
		lexer.UseTokenType(Keyword_answer),
		lexer.UseTokenType(Token_ID),
		lexer.UseTokenType(Token_INT),
		lexer.UseTokenType(Token_STRING),
		lexer.UseTokenType(Token_WS).WithModifier(core.SkippedModifier),
		lexer.UseTokenType(Token_SL_COMMENT).WithModifier(core.CommentModifier),
		lexer.UseTokenType(Token_ML_COMMENT).WithModifier(core.CommentModifier),
	)
	return lexer.NewDefaultLexer(sc, TokenMode_default, modes...)
}
